"""Minimal Streamable-HTTP MCP client for Unreal 5.8 (127.0.0.1:8000/mcp)."""
import json
import sys
import uuid
import urllib.request

URL = "http://127.0.0.1:8000/mcp"
SESSION = None


def rpc(method, params=None, notify=False):
    global SESSION
    body = {"jsonrpc": "2.0", "method": method}
    if not notify:
        body["id"] = str(uuid.uuid4())
    if params is not None:
        body["params"] = params
    data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(URL, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    req.add_header("Accept", "application/json, text/event-stream")
    req.add_header("Origin", "http://127.0.0.1:8000")
    if SESSION:
        req.add_header("Mcp-Session-Id", SESSION)
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            sid = resp.headers.get("Mcp-Session-Id")
            if sid:
                SESSION = sid
            raw = resp.read().decode("utf-8", "replace")
            if raw.startswith("event:") or "data:" in raw[:20]:
                # SSE wrapper
                chunks = []
                for line in raw.splitlines():
                    if line.startswith("data:"):
                        chunks.append(line[5:].strip())
                raw = "\n".join(chunks)
            return json.loads(raw) if raw else {}
    except Exception as exc:
        err = ""
        if hasattr(exc, "read"):
            err = exc.read().decode("utf-8", "replace")[:2000]
        raise RuntimeError("{0} {1}".format(exc, err))


def main():
    action = sys.argv[1] if len(sys.argv) > 1 else "list"
    init = rpc("initialize", {
        "protocolVersion": "2024-11-05",
        "capabilities": {},
        "clientInfo": {"name": "laptop-agent", "version": "1.0"},
    })
    rpc("notifications/initialized", notify=True)
    if action == "init":
        print(json.dumps(init, indent=2)[:4000])
        return 0
    if action == "list":
        listed = rpc("tools/list", {})
        print(json.dumps(listed, indent=2)[:8000])
        return 0
    if action == "call":
        name = sys.argv[2]
        args = json.loads(sys.argv[3]) if len(sys.argv) > 3 else {}
        out = rpc("tools/call", {"name": name, "arguments": args})
        print(json.dumps(out, indent=2)[:8000])
        return 0
    print("usage: _ue_mcp.py init|list|call <tool> [json-args]")
    return 1


if __name__ == "__main__":
    sys.exit(main())

